            'ရှမ်းပြည်နယ်(အရှေ့ပိုင်း)၊ ကျိုင်းတုံမြို့ ကျက်သရေဆောင် မဟာမြတ်မုနိဘုရားကြီး နှစ်(၁၀၀)ပြည့်အထိမ်းအမှတ် ရတနာစိန်ဖူးတော်၊ ရွှေထီးတော် တင်လှူပူဇော်ပွဲ နှင့် ဗုဒ္ဓါဘိသေက အနေကဇာတင်မဟာမင်္ဂလာအခမ်းအနားကို သာသနာတော်နှစ် ၂၅၆၅ ခုနှစ်၊ ကောဇာ သက္ကရာဇ် ၁၃၈၃ ခုနှစ်၊ တပို့တွဲလပြည့်နေ့ ယနေ့ နံနက်ပိုင်း တွင် ကျင်းပပြုလုပ်ရာ ကျိုင်းတုံမြို့၊ ကျိုင်းယင်းကျောင်းတိုက်၊ ဦးစီးပဓာန နာယက အဂ္ဂမဟာသဒ္ဓမ္မဇောတိကဓဇ ဘဒ္ဒန္တ ခေမာစာရ အမှူးပြုသည့် ဆရာတော်၊ သံဃာ တော် အရှင်သူမြတ်များ ကြွရောက်ချီးမြှင့်တော်မူကြသည်။\n\nအဆိုပါ အခမ်းအနားသို့ နိုင်ငံတော်စီမံအုပ်ချုပ်ရေးကောင်စီဥက္ကဋ္ဌ၊ (ယခင်)နိုင်ငံတော် ဝန်ကြီးချုပ်၊ (ယခု)နိုင်ငံတော်သမ္မတ ဗိုလ်ချုပ်မှူးကြီး မင်းအောင်လှိုင်၊ ဇနီးဒေါ်ကြူကြူလှနှင့် မိသားစုဝင်များ၊ နိုင်ငံတော်စီမံ အုပ်ချုပ်ရေးကောင်စီဝင်များဖြစ်ကြသည့် ဒုတိယဗိုလ်ချုပ်ကြီး မိုးမြင့်ထွန်း၊ ဦးစိုင်းလုံးဆိုင်၊ ဦးရွှေကြိမ်း၊ ပြည်ထောင်စုဝန်ကြီးများဖြစ်ကြသည့် ဒုတိယဗိုလ်ချုပ်ကြီး ထွန်းထွန်းနောင်၊ ဦးကိုကို၊ ဦးလှမိုး၊ ဒေါက်တာညွန့်ဖေ၊ ဒေါက်တာ သက်ခိုင်ဝင်း၊ ရှမ်းပြည်နယ် ဝန်ကြီးချုပ် ဒေါက်တာ ကျော်ထွန်း၊ နိုင်ငံတော်စီမံအုပ်ချုပ်ရေး ကောင်စီ ဥက္ကဋ္ဌ၏အကြံပေးအဖွဲ့ အဖွဲ့ဝင် ဒေါက်တာ ဒေါ်ရင်ရင်နွယ်၊ ကာကွယ်ရေးဦးစီးချုပ် (ရေ) ဗိုလ်ချုပ်ကြီး မိုးအောင်နှင့် ဇနီး၊ ကာကွယ်ရေးဦးစီးချုပ်(လေ) ဗိုလ်ချုပ်ကြီး ထွန်းအောင်နှင့် ဇနီး၊ ကာကွယ်ရေးဦးစီးချုပ်ရုံးမှ တပ်မတော်အရာရှိ ကြီးများနှင့် ဇနီးများ၊ တြိဂံဒေသတိုင်းစစ်ဌာနချုပ် တိုင်းမှူး ဗိုလ်ချုပ် မျိုးမင်းထွန်း  နှင့် တာဝန် ရှိသူများ၊ ဖိတ်ကြားထားသည့် ဧည့်သည်တော်များ၊ စေတနာရှင်အလှူရှင်များ၊ အရာရှိ၊ စစ်သည်၊ မိသားစုများ၊ ဝတ်အသင်းအဖွဲ့များ၊ ဒေသခံတိုင်းရင်းသား ပြည်သူများနှင့် ရိုးရာယဉ်ကျေးမှုအသင်းအဖွဲ့များ တက်ရောက်ကြသည်။',
