            'မြေညီထပ်အတွင်း ထိုင်တော်မူဆင်းတုတော်(မေတ္တာဘုရား)နှင့် အထက်ပစ္စယံအတွင်းရှိ ရပ်တော်မူဆင်းတုတော်(အရိမေတ္တယျဘုရား)တို့ကို ကြေးဖြင့် သွန်းလောင်းပူဇော်ခဲ့ပါသည်။ အရန်စေတီတော်(၄)ဆူနှင့် မြေညီထပ်အဝင် ရပ်တော်မူဆင်းတုတော်များ၊ စေတီတော် ပန်းတည်ခုံရှိ ရပ်တော်မူ(၂-ဆူ)နှင့် မုဒြာမျိုးစုံ ဆင်းတုတော်များ၊ စေတီတော်ကိုယ်ထည်နှင့် ပန်းတည်ခုံပေါ်ရှိ ကွန်းတောင်စေတီငယ်များနှင့် ရုပ်ပွားတော်များကို ဒေသသဲကျောက်ဖြင့် ထုဆစ်ပူဇော်ခဲ့ပါသည်။ ရင်ပြင်တော် မဟာရာမ်တံတိုင်းကို အင်္ဂတေပန်းဖြင့် တည်ဆောက်ကာ အမြင့်(၂၇-လက်မ)ရှိ ငြိမ်းချမ်းရေးခေါင်းလောင်း(၂-လုံး)ကို ကြေးဖြင့် သွန်းလောင်း၍ အင်္ဂတေတိုင်များဖြင့် တပ်ဆင်ခဲ့ပါသည်။',
            'ဤလုပ်ငန်းများကို ကာကွယ်ရေးဦးစီးချုပ်ရုံး(ကြည်း)မှ အရာရှိ/စစ်သည်များ ဗိသုကာပညာရှင် ဦးစန်းမောင်နှင့်အဖွဲ့၊ ကျောက်ဆစ်ပညာရှင် ပါမောက္ခ ဦးဇော်သန်းထွဋ် (အမျိုးသားယဉ်ကျေးမှုနှင့် အနုပညာတက္ကသိုလ်၊ မန္တလေး)အဖွဲ့၊ ကျောက်ဆစ်ပညာရှင် ဦးကျော်ကျော်လွင်၊ လ/ထ ကထိက(ငြိမ်း)၊ အမျိုးသားယဉ်ကျေးမှုနှင့် အနုပညာတက္ကသိုလ်၊ ရန်ကုန်အဖွဲ့နှင့် မြန်မာ့မှုပညာရှင် ဦးကျင်သိန်း အဖွဲ့တို့က ဘက်စုံတည်ဆောက်ပူဇော်ခဲ့ကြပါသည်။',
