            '(၁-၆-၂၀၀၈) ရက်နေ့တွင် ဆွမ်းပန်းရေချမ်းဆီမီး ပူဇော်ကပ်လှူပြီး ဆရာတော် ကျောက်စီထပ်ထံမှ ငါးပါးသီလ ခံယူဆောက်တည်၍ ပြုပြင်ရန် လုပ်ငန်းများ စတင်ဆောင်ရွက်ခဲ့ပါသည်။ (၂-၆-၂၀၀၈) ရက်နေ့တွင် ဆရာတော်ကိုယ်တိုင်ဦးစီး၍ ရုပ်ပွားတော်မြတ်ကြီးအား ဦးခေါင်းတော်မှစ၍ ခါးတော်အောက်ပိုင်းအထိ သံချည်သံကွေးများဖြင့် အချိုးကျရစ်ခွေ၍ အဆင့်ဆင့် ဂရုတစိုက် လုပ်ဆောင်ခဲ့ပါသည်။',
