            'ဂုံရှမ်းဂိုဏ်းချုပ် ကျိုင်းယင်းကျောင်းတိုက် ပဓာနနာယကဆရာတော် ဘဒ္ဒန္တခေမာစာရနှင့် သီလဓမ္မကုန်းသာကျောင်းတိုက် ပဓာနနာယကဆရာတော် ဘဒ္ဒန္တကောဝိဒတို့၏ ၂၀၂၂-ခုနှစ်၊ စက်တင်ဘာလ (၉)ရက်နေ့ ဩဝါဒစကား မိန့်ကြားချက်အရ တြိဂံဒေသ တိုင်းစစ်ဌာနချုပ် တိုင်းမှူး ဗိုလ်ချုပ်နီလင်းအောင်မှ ဦးဆောင်ပြီး ၂၀၂၂-ခုနှစ်၊ နိုဝင်ဘာလ (၁၃)ရက်နေ့တွင် ဂန္ဓကုဋိကျောင်းဆောင်တော်ကြီးအား အသစ်ပြန်လည်ပြုပြင် မွမ်းမံခြင်းလုပ်ငန်းကို စတင်ဆောင်ရွက်ခဲ့ပါသည်။ ၂၀၂၃-ခုနှစ်၊ ဇွန်လ(၂)ရက်၊ သောကြာနေ့တွင် ဂန္ဓကုဋိကျောင်းဆောင်တော်သစ်ကြီးအား ထီးတော်တင်လှူခြင်းနှင့် ရေစက်သွန်ချမင်္ဂလာ အခမ်းအနားများ ကျင်းပပြုလုပ်၍ အောင်မြင်စွာ ပြုပြင်လှူဒါန်းနိုင်ခဲ့ပါသည်။',
